-- Inventário somente leitura. Valores de registros não saem desta consulta: só contagens e hashes.
WITH tab AS (
 SELECT n.nspname,c.relname,c.relrowsecurity,c.relforcerowsecurity,c.relowner,c.relacl,
 query_to_xml(format($q$SELECT count(*) n,encode(sha256(convert_to(coalesce(string_agg(j,E'\n' ORDER BY j),''),'UTF8')),'hex') h FROM (SELECT to_jsonb(t)::text j FROM %I.%I t) s$q$,n.nspname,c.relname),false,true,'') AS content
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE c.relkind IN('r','p') AND n.nspname<>'information_schema' AND n.nspname!~'^pg_' AND NOT(n.nspname='public' AND c.relname='spatial_ref_sys')
), data AS (
 SELECT coalesce(jsonb_agg(jsonb_build_object('name',nspname||'.'||relname,'rows',((xpath('/row/n/text()',content))[1]::text)::bigint,'sha256',(xpath('/row/h/text()',content))[1]::text) ORDER BY nspname,relname),'[]') AS inventory FROM tab
), security AS (
 SELECT jsonb_build_object(
 'tables',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',nspname||'.'||relname,'rls',relrowsecurity,'forced',relforcerowsecurity,'owner',relowner::regrole::text,'grants',(SELECT jsonb_agg(jsonb_build_array(grantee::regrole::text,grantor::regrole::text,privilege_type,is_grantable) ORDER BY grantee,grantor,privilege_type,is_grantable) FROM aclexplode(coalesce(relacl,acldefault('r',relowner))))) ORDER BY nspname,relname),'[]') FROM tab),
 'policies',(SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY schemaname,tablename,policyname),'[]') FROM pg_policies p),
 'functions',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',n.nspname||'.'||p.proname,'arguments',pg_get_function_identity_arguments(p.oid),'definition',pg_get_functiondef(p.oid),'owner',p.proowner::regrole::text,'grants',(SELECT jsonb_agg(jsonb_build_array(grantee::regrole::text,grantor::regrole::text,privilege_type,is_grantable) ORDER BY grantee,grantor,privilege_type,is_grantable) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))))) ORDER BY n.nspname,p.proname,pg_get_function_identity_arguments(p.oid)),'[]') FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname<>'information_schema' AND n.nspname!~'^pg_' AND p.prokind IN('f','p') AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e')),
 'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',n.nspname||'.'||c.relname,'name',t.tgname,'definition',pg_get_triggerdef(t.oid),'enabled',t.tgenabled) ORDER BY n.nspname,c.relname,t.tgname),'[]') FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE NOT t.tgisinternal AND n.nspname!~'^pg_'),
 'constraints',(SELECT coalesce(jsonb_agg(jsonb_build_object('table',n.nspname||'.'||c.relname,'name',k.conname,'definition',pg_get_constraintdef(k.oid)) ORDER BY n.nspname,c.relname,k.conname),'[]') FROM pg_constraint k JOIN pg_class c ON c.oid=k.conrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname!~'^pg_' AND n.nspname<>'information_schema'),
 'indexes',(SELECT coalesce(jsonb_agg(to_jsonb(i) ORDER BY schemaname,tablename,indexname),'[]') FROM pg_indexes i WHERE schemaname!~'^pg_' AND schemaname<>'information_schema'),
 'schemas',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',nspname,'owner',nspowner::regrole::text,'grants',(SELECT jsonb_agg(jsonb_build_array(grantee::regrole::text,grantor::regrole::text,privilege_type,is_grantable) ORDER BY grantee,grantor,privilege_type,is_grantable) FROM aclexplode(coalesce(nspacl,acldefault('n',nspowner))))) ORDER BY nspname),'[]') FROM pg_namespace WHERE nspname!~'^pg_' AND nspname<>'information_schema'),
 'defaults',(SELECT coalesce(jsonb_agg(jsonb_build_object('owner',d.defaclrole::regrole::text,'schema',coalesce(n.nspname,''),'type',d.defaclobjtype,'grants',(SELECT jsonb_agg(jsonb_build_array(grantee::regrole::text,grantor::regrole::text,privilege_type,is_grantable) ORDER BY grantee,grantor,privilege_type,is_grantable) FROM aclexplode(d.defaclacl))) ORDER BY d.defaclrole,coalesce(n.nspname,''),d.defaclobjtype),'[]') FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace),
 'extensions',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname) ORDER BY e.extname),'[]') FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace),
 'sequences',(SELECT coalesce(jsonb_agg(to_jsonb(s)-'last_value' ORDER BY schemaname,sequencename),'[]') FROM pg_sequences s)
 ) AS inventory
)
SELECT jsonb_build_object('data',data.inventory,'securitySha256',encode(sha256(convert_to(security.inventory::text,'UTF8')),'hex'),
 'security',security.inventory,'sequenceFloors',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',schemaname||'.'||sequencename,'value',last_value,'increment',increment_by) ORDER BY schemaname,sequencename),'[]') FROM pg_sequences)) FROM data,security;
